import type { ChipProps } from "tscircuit"
// Exact JLCPCB-linked EasyEDA library footprint for C5197687 (T113-S3).
// Imported 2026-09-11 with: tsci import C5197687 --jlcpcb --use-exact-footprint
// This supplier land pattern is not a claim of manufacturer qualification.
// Package: 14 mm body, 0.4 mm lead pitch, nominal 5.72 mm exposed metal pad
// (Allwinner datasheet v1.6). Supplier PCB copper land: 5.5999888 mm square.
// Lead lands: 1.459992 x 0.1999996 mm, nominal centers at +/-7.629906 mm.
// Supplier pin 1 starts at bottom-left; rotate the footprint -90 degrees to
// preserve our board's pin 1 at upper-left on the left side. Schematic stays upright.
// Supplier CAD URLs are intentionally omitted for reproducible local builds.
// All copper below is component pad geometry, not manual routes or vias.
import pins from "./t113-pins.json"
const pinLabels = Object.fromEntries(
  pins.map(({ pin, tsxName }) => [`pin${pin}`, [tsxName]]),
)
const pinAttributes = Object.fromEntries(
  pins.flatMap(
    ({
      tsxName,
    }): [string, NonNullable<ChipProps["pinAttributes"]>[string]][] => {
      if (/^P[B-G]\d+$/.test(tsxName)) return [[tsxName, { isGpio: true }]]
      if (["GND", "AGND"].includes(tsxName))
        return [[tsxName, { requiresGround: true }]]
      if (/^(VCC_|VDD|AVCC|HPVCC|LDO_IN)/.test(tsxName))
        return [[tsxName, { requiresPower: true }]]
      if (tsxName === "LDOA_OUT")
        return [[tsxName, { providesPower: true, providesVoltage: "1.8V" }]]
      if (tsxName === "LDOB_OUT") return [[tsxName, { providesPower: true }]]
      if (tsxName === "NC0") return [[tsxName, { doNotConnect: true }]]
      return []
    },
  ),
)

